import {SCENARIOS,rankCandidates,timeLabel,compliant,storyFor} from './model.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={scenario:'rebound',policy:'naive',response:'observe',step:0,layer:'loading',playing:false,speed:1,selected:null,lambda:1,planned:null,experiment:false};
let data,homesById,candidatesById,ranked=[],timer,toastTimer,view={x:0,y:0,z:1},projection;
const dialog=$('#detail-dialog');
const fmt=(n,d=0)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function current(){const key=state.policy+(state.scenario==='covert'&&state.response==='quarantine'?'_quarantine':'');return data.replays[state.scenario][key][state.step]}
function rank(){ranked=rankCandidates(data.candidates.candidates,state.lambda);candidatesById=new Map(ranked.map(c=>[c.id,c]));}
function stop(){state.playing=false;clearInterval(timer);$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play replay')}
function play(){if(!data)return;stop();if(state.step===12)state.step=0;state.playing=true;$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause replay');timer=setInterval(()=>{state.step++;if(state.step>=12){state.step=12;stop()}render()},1600/state.speed);render()}
function setScenario(scenario){if(!SCENARIOS[scenario])throw new Error('Unknown scenario');stop();view={x:0,y:0,z:1};Object.assign(state,{scenario,step:0,policy:scenario==='covert'?'aware':'naive',response:'observe',selected:null,experiment:false,layer:scenario==='covert'?'detector':'loading'});render()}
function setPolicy(policy){if(!['naive','aware'].includes(policy))throw new Error('Unknown policy');state.policy=policy;render();toast(policy==='aware'?'Dispatch now follows electrical headroom.':'Every available battery receives an equal share.')}
function setStep(step){if(!Number.isInteger(step)||step<0||step>12)throw new Error('Step must be an integer from 0 to 12');stop();state.step=step;render()}
function setLayer(layer){if(!['loading','voltage','score','detector'].includes(layer))throw new Error('Unknown layer');state.layer=layer;renderMap();$$('[data-layer]').forEach(el=>{el.classList.toggle('active',el.dataset.layer===layer);el.setAttribute('aria-pressed',el.dataset.layer===layer)})}
function selectHome(id){if(!homesById.has(id))throw new Error('Unknown home');stop();state.selected=id;state.experiment=false;render();}
function renderStats(f){
 const fourth=state.scenario==='covert'?['Flagged batteries',fmt(f.flags.length),' / 96',`${f.falsePositiveRate}% clean-fleet false positives`,f.flags.length?'danger':'']:['Market position forgone',fmt(f.shortfallKW),' kW',`${fmt(Math.abs(f.deliveredKW))} kW ${f.deliveredKW<0?'discharging':'charging'}`,f.shortfallKW>50?'warning':''];
 const cells=[['Feeder demand',fmt(f.feederMW,2),' MW','OpenDSS power flow',''],['Highest transformer load',fmt(f.maxLoading,1),' %',`${f.overloaded} / 379 over the 100% limit`,f.overloaded?'danger':''],['Lowest home voltage',fmt(f.minVoltage,3),' pu',`${f.voltageViolations} homes outside 0.95–1.05 pu`,f.voltageViolations?'danger':''],fourth];
 $('#stats').innerHTML=cells.map(([label,value,unit,foot,cls])=>`<div class="stat ${cls}"><span>${label}</span><strong>${value}<small>${unit}</small></strong><span class="stat-foot">${foot}</span></div>`).join('');
}
function render(){if(!data)return;const f=current(),s=SCENARIOS[state.scenario];
 $('#scenario-title').innerHTML=s.name+'<span class="title-period">.</span>';
 $$('[data-scenario]').forEach(el=>{const on=el.dataset.scenario===state.scenario;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on)});
 renderStats(f);renderMap();renderPanel(f);
 $('#time-display').textContent=timeLabel(f.minute);$('#timeline').value=state.step;$('#timeline').setAttribute('aria-valuetext',timeLabel(f.minute));
 $('.timeline-markers').innerHTML=s.markers.map(t=>`<span>${t}</span>`).join('');
 $('#event-caption').textContent=storyFor(state.scenario,f,state.policy,state.response).title;
 $('#map-count').textContent=`1,010 homes · 96 batteries`;
 $$('[data-layer]').forEach(el=>{el.classList.toggle('active',el.dataset.layer===state.layer);el.setAttribute('aria-pressed',el.dataset.layer===state.layer)});
 $('.decision-dock h2').textContent=state.planned?`${homesById.get(state.planned).label} is your next move.`:'Where should the next battery go?';
 $('.decision-dock p').textContent=state.planned?'A planned candidate, tested at three solved stress snapshots.':'One neighborhood. Different value at every connection.';
}
function renderPanel(f){if(state.selected){renderHome(f);return}const s=SCENARIOS[state.scenario],story=storyFor(state.scenario,f,state.policy,state.response);
 const signal=state.scenario==='covert'?`<div class="signal-strip"><span class="${f.trackingOK?'good':'danger'}">${f.trackingOK?'✓':'!'} Market tracking ${f.trackingOK?'passes':'fails'}</span><span>±${fmt(f.toleranceKW)} kW tolerance</span></div>`:'';
 let action='Run the scenario';
 if(state.step>0){if(state.scenario==='rebound'&&state.step>=3&&state.policy==='naive')action='Use feeder-aware dispatch';else if(state.scenario==='covert'&&f.flags.length&&state.response==='observe')action='Compare automatic quarantine';else if(state.step>=9)action='Choose the next battery';else action='Jump to the next event'}
 $('#mission').innerHTML=`<div class="mission-top"><span class="eyebrow">MISSION ${s.number}</span><span class="difficulty">${s.difficulty}</span></div><h2>${s.headline}</h2><p class="mission-copy">${s.intro}</p><div class="mission-objective"><span class="eyebrow">YOUR OBJECTIVE</span><p>${s.objective}</p></div><div class="eyebrow dispatch-label">DISPATCH STRATEGY</div><div class="segmented" role="group" aria-label="Dispatch strategy"><button data-policy="naive" aria-pressed="${state.policy==='naive'}" class="${state.policy==='naive'?'active':''}">Even split</button><button data-policy="aware" aria-pressed="${state.policy==='aware'}" class="${state.policy==='aware'?'active':''}">Feeder-aware</button></div>${signal}<div class="story"><span class="story-time">${timeLabel(f.minute)}</span><h3>${story.title}</h3><p>${story.text}</p></div><button id="next-event" class="primary">${action}<span>↗</span></button><div class="mission-footer"><span>0${story.chapter} / 04</span><span>${state.scenario==='covert'?'FICTIONAL ADVERSARY · SIMULATED SIGNAL':'SCRIPTED INPUTS · SOLVED PHYSICS'}</span></div>`;
 $$('[data-policy]').forEach(b=>b.onclick=()=>setPolicy(b.dataset.policy));
 $('#next-event').onclick=()=>{
  if(state.step===0){play();return}
  if(state.scenario==='rebound'&&state.step>=3&&state.policy==='naive'){setPolicy('aware');return}
  if(state.scenario==='covert'&&f.flags.length&&state.response==='observe'){state.response='quarantine';state.step=0;play();toast('Replaying automatic quarantine from first detection.');return}
  if(state.step>=9){openSiting();return}setStep(state.step<3?3:state.step<7?7:12)
 };
}
function renderHome(f){const h=homesById.get(state.selected),c=candidatesById.get(h.id),tf=data.topology.transformers[h.tf];
 const telemetry=f.detector[h.id];
 const metrics=`<div class="home-metrics"><div><span>Transformer</span><strong class="${f.loading[h.tf]>100?'danger':''}">${fmt(f.loading[h.tf],1)}<small>%</small></strong></div><div><span>Home voltage</span><strong class="${f.voltage[h.index]<.95?'danger':''}">${fmt(f.voltage[h.index],3)}<small>pu</small></strong></div></div>`;
 let body='';
 if(h.battery){body=`<div class="connection-badge">▰ EXISTING CORE · 20 kW / 37 kWh usable*</div>${metrics}<div class="home-metrics"><div><span>Battery power</span><strong>${fmt(f.powers[h.id],1)}<small>kW</small></strong></div><div><span>State of charge</span><strong>${fmt(f.soc[h.id]*100)}<small>%</small></strong></div></div><div class="soc-track"><i style="width:${f.soc[h.id]*100}%"></i><span></span></div><p class="small-note">Positive power charges. 20% is reserved for backup. *Usable energy is an assumption.</p>${telemetry?`<div class="evidence"><span class="eyebrow">DETECTOR EVIDENCE</span><p>Residual RMS <b>${fmt(telemetry.rms*1000)} W</b></p><p>Lag correlation <b>${fmt(telemetry.correlation,2)}</b></p><p>Voltage residual <b>${fmt(telemetry.voltageDelta*1000,3)} mpu</b></p><p>Status <b class="${telemetry.flagged?'danger':'good'}">${f.quarantined.includes(h.id)?'Quarantined':telemetry.flagged?'Flagged':'Observing'}</b></p></div>`:''}`}
 else if(c){body=`<div class="connection-badge">+ CANDIDATE CONNECTION</div>${metrics}<div class="candidate-score"><div><span class="eyebrow">NEXT-BATTERY SCORE</span><strong>${fmt(c.score,1)}</strong></div><div><span class="rank-label">RANK</span><strong>#${c.rank}<small> / ${ranked.length}</small></strong></div></div><p class="small-note">Value ${fmt(c.value,1)} − λ ${fmt(state.lambda,1)} × risk ${fmt(c.risk,1)}. Dimensionless demo weights.</p><div class="evidence"><p>Transformer rating <b>${tf.kva} kVA</b></p><p>Charge headroom* <b>${fmt(c.headroomKW,1)} kW</b></p><p>Electrical distance <b>${fmt(h.distance,2)} km</b></p></div><p class="small-note">*At the rebound stress snapshot, with feeder-aware dispatch.</p><button class="primary" id="test-battery">Test a battery here <span>+</span></button><button class="text-action" id="compare-candidates">Compare candidate homes ↗</button>`}
 else body=metrics+'<p class="mission-copy">This commercial connection is outside the 120/240 V residential Core model.</p>';
 $('#mission').innerHTML=`<div class="mission-top"><button class="back-button" id="back-mission">← Back to mission</button><span class="eyebrow">${h.battery?'BATTERY':'SITE'}</span></div><h2>${h.label}</h2><p class="home-location">${h.district} <span>· illustrative district name</span></p>${body}<div class="mission-footer"><span>${esc(h.id)}</span><span>SMART-DS CONNECTION</span></div>`;
 $('#back-mission').onclick=()=>{state.selected=null;render()};
 if(c){$('#test-battery').onclick=()=>openExperiment(h.id);$('#compare-candidates').onclick=openSiting}
}
function point(c){return [90+(c[0]-projection.xmin)/projection.dx*820,120+(projection.ymax-c[1])/projection.dy*480]}
function renderMap(){if(!data||!projection)return;const f=current();let flagSet=new Set(f.flags),quarantine=new Set(f.quarantined);
 const color=h=>{
  if(state.layer==='score'){const c=candidatesById.get(h.id);return c?(c.rank<=10?'#deff8e':c.rank<=150?'#9fc77a':c.score<0?'#f3906e':'#527857'):'#3a5041'}
  if(state.layer==='detector')return quarantine.has(h.id)?'#b5a0fa':flagSet.has(h.id)?'#ff887a':h.battery?'#a8db84':'#46664c';
  const value=state.layer==='loading'?f.loading[h.tf]:f.voltage[h.index];
  return state.layer==='loading'?(value>100?'#ff8472':value>85?'#eac77b':'#80b994'):(value<.95||(f.voltageMax?.[h.index]??value)>1.05?'#ff8472':value<.97?'#eac77b':'#80b994')
 };
 const edgeColor=new Map();data.topology.homes.forEach(h=>edgeColor.set(h.id,color(h)));
 let svg=data.topology.edges.map(e=>{const a=point(e.coordinates[0]),b=point(e.coordinates[1]),stroke=edgeColor.get(e.b)||edgeColor.get(e.a)||'#63826c';const isWeak=e.id===data.topology.shaping.weakLine;return `<path class="network-line${isWeak?' weak-line':''}" d="M${a}L${b}" stroke="${isWeak?'#b5be8f':stroke}" fill="none" opacity="${isWeak?.8:.53}" stroke-width="${isWeak?2:1}" ${isWeak?'stroke-dasharray="5 4"':''}/>`}).join('');
 svg+=data.topology.homes.map(h=>{const p=point(h.coordinates),selected=state.selected===h.id,planned=state.planned===h.id,c=candidatesById.get(h.id),highlight=state.layer==='score'&&c?.rank<=10,bad=(state.layer==='detector'?flagSet.has(h.id):f.loading[h.tf]>100||f.voltage[h.index]<.95||(f.voltageMax?.[h.index]??0)>1.05),radius=h.battery?3.1:2;
  return `${(bad||highlight)?`<circle cx="${p[0]}" cy="${p[1]}" r="${highlight?10:7}" fill="${color(h)}" opacity=".10"/>`:''}<${h.battery?'rect':'circle'} class="home-node" aria-hidden="true" data-home="${h.id}" ${h.battery?`x="${p[0]-2.7}" y="${p[1]-3.6}" width="5.4" height="7.2" rx="1"`:`cx="${p[0]}" cy="${p[1]}" r="${highlight?4:radius}"`} fill="${color(h)}" stroke="${h.battery?'#cbeac3':'#17291c'}" stroke-width=".45"><title>${h.label} · ${fmt(f.loading[h.tf])}% transformer load · ${f.voltage[h.index]} pu${c?' · rank '+c.rank:''}</title></${h.battery?'rect':'circle'}>${selected||planned?`<circle class="selection-ring" cx="${p[0]}" cy="${p[1]}" r="13"/>`:''}`;
 }).join('');
 const sp=point(data.topology.source);svg+=`<g><rect x="${sp[0]-9}" y="${sp[1]-9}" width="18" height="18" rx="3" fill="#c4ee85"/><path d="M${sp[0]+2} ${sp[1]-6}l-6 8h5l-2 5 6-9h-4z" fill="#20311c"/><text class="map-label" x="${sp[0]+19}" y="${sp[1]+3}">SUBSTATION</text></g>`;
 // District names are narrative labels, anchored to actual modeled home coordinates.
 for(const name of ['Cedar Grove','Northbank','West Ridge']){const group=data.topology.homes.filter(h=>h.district===name);const cp=point([group.reduce((s,h)=>s+h.coordinates[0],0)/group.length,group.reduce((s,h)=>s+h.coordinates[1],0)/group.length]);svg+=`<text class="map-label" x="${cp[0]+24}" y="${cp[1]-19}">${name.toUpperCase()}</text>`}
 $('#map-world').innerHTML=svg;transformView();$('#map-loading').hidden=true;
 const legends={loading:'<span class="legend-line"></span> Below 85% <span class="legend-line amber"></span> 85–100% <span class="legend-line red"></span> Over 100%',voltage:'<span class="legend-line"></span> 0.97–1.05 pu <span class="legend-line amber"></span> 0.95–0.97 <span class="legend-line red"></span> Outside limits',score:'<span class="legend-line"></span> Top 10 sites <span class="legend-line amber"></span> Lower score <span class="legend-battery"></span> Existing battery',detector:'<span class="legend-line"></span> Observing <span class="legend-line red"></span> Flagged <span class="legend-line" style="background:#b5a0fa"></span> Quarantined'};
 $('#legend').innerHTML=legends[state.layer]+(['loading','voltage'].includes(state.layer)?'<span class="legend-battery"></span> Battery':'');
}
function transformView(){$('#map-world').setAttribute('transform',`translate(${view.x} ${view.y}) translate(500 350) scale(${view.z}) translate(-500 -350)`)}
function zoom(by){view.z=Math.max(.7,Math.min(8,view.z*by));transformView()}
function showDialog(html){stop();$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal()}
function openSiting(){if(!data)return;setLayer('score');
 showDialog(`<span class="eyebrow">THE NEXT BATTERY</span><h2 class="dialog-title">Location changes the value.</h2><p class="dialog-intro">Rank ${ranked.length} uninstalled residential connections. Each has six OpenDSS counterfactuals: charging and discharging in all three scenarios. The score is a comparison, not a dollar forecast.</p><div class="risk-control"><label for="risk-weight">Risk aversion <span>λ = <b id="lambda-value">${state.lambda.toFixed(1)}</b></span></label><input id="risk-weight" type="range" min="0" max="3" step=".1" value="${state.lambda}" aria-label="Risk aversion"><div><span>Prioritize support</span><span>Prioritize charge safety</span></div></div><div class="score-formula">Score = <b>20 + 0.75 × thermal relief + 15 × voltage support</b> − λ × <b>charge stress + voltage risk + cohort concentration</b><details><summary>Inspect all scoring weights</summary><p>Thermal relief: transformer loading percentage points. Voltage support: milliper-unit improvement in the feeder minimum. Charge risk = 0.7 × max(0, local loading − 80). Voltage risk = 1,200 × max(0, 0.97 − home voltage). Cedar concentration penalty = 8. All weights are demo assumptions.</p></details></div><div id="candidate-list"></div><label class="all-candidates-label" for="candidate-select">Inspect any candidate</label><select id="candidate-select"><option value="">Choose a home…</option>${ranked.map(c=>`<option value="${c.id}">${homesById.get(c.id).label} · ${homesById.get(c.id).district} · ${c.id}</option>`).join('')}</select><div class="hosting-note"><span class="eyebrow">HOSTING SWEEP · FIXED λ = 1</span><p id="hosting-copy"></p><span>Ranked queue; 20 kW requested per unit; the aware controller may curtail. This is a bounded queue experiment, not a guaranteed installation limit.</span></div>`);
 renderCandidateList();
 $('#risk-weight').oninput=e=>{state.lambda=Number(e.target.value);$('#lambda-value').textContent=state.lambda.toFixed(1);rank();renderCandidateList();renderMap()};
 $('#candidate-select').onchange=e=>{if(e.target.value){const id=e.target.value;dialog.close();selectHome(id);focusHome(id)}};
 const cap=data.candidates.hosting;$('#hosting-copy').textContent=`Even split: ${cap.naive.addedBeforeViolation} additional homes before a violation${cap.naive.addedBeforeViolation===0?' (the existing fleet is already constrained)':''}. Feeder-aware: ${cap.aware.queueExhausted?'all ':''}${cap.aware.addedBeforeViolation}${cap.aware.queueExhausted?' tested homes stayed within limits with curtailment':' additional homes before a violation'}.`;
}
function renderCandidateList(){const list=$('#candidate-list');if(!list)return;
 list.innerHTML=`<div class="candidate-header"><span>RANK / CONNECTION</span><span>VALUE</span><span>RISK</span><span>SCORE</span><span></span></div>`+ranked.slice(0,10).map(c=>{const h=homesById.get(c.id);return `<button class="candidate-row" data-candidate="${c.id}" aria-label="Inspect ${h.label}, rank ${c.rank}"><span class="candidate-name"><b>${String(c.rank).padStart(2,'0')}</b><span>${h.label}<small>${h.district}</small></span></span><span>${fmt(c.value,1)}</span><span>${fmt(c.risk,1)}</span><strong>${fmt(c.score,1)}</strong><span>↗</span></button>`}).join('');
 $$('[data-candidate]').forEach(b=>b.onclick=()=>{dialog.close();selectHome(b.dataset.candidate);focusHome(b.dataset.candidate)});
}
function focusHome(id){const p=point(homesById.get(id).coordinates);view={z:2.8,x:(500-p[0])*2.8,y:(350-p[1])*2.8};transformView();$('#mission').scrollIntoView({behavior:'smooth',block:'nearest'})}
function openExperiment(id){const c=candidatesById.get(id),h=homesById.get(id);if(!c)throw new Error('This home is not an eligible candidate');state.experiment=true;
 showDialog(`<span class="eyebrow">ONE BATTERY · SIX SOLVED COUNTERFACTUALS</span><h2 class="dialog-title">Test ${h.label}.</h2><p class="dialog-intro">Add one Core at this connection, then re-solve. Each result is a stored OpenDSS snapshot with feeder-aware dispatch on the existing fleet. This compares full ±20 kW operation; it does not change the running replay.</p><div class="experiment-heading"><span>${h.district} · rank #${c.rank}</span><span>37 kWh usable · ASSUMPTION</span></div><div class="experiment-grid">${Object.entries(SCENARIOS).map(([key,s])=>{const base=data.candidates.contexts[key].baseline;return `<article class="experiment-card"><span class="eyebrow">${s.number} / ${timeLabel(s.start+35)}</span><h3>${s.name}</h3><div class="experiment-baseline">Before: ${fmt(base.maxLoading,1)}% · ${fmt(base.minVoltage,3)} pu</div>${['discharge','charge'].map(mode=>{const e=c.effects[key][mode];return `<div class="experiment-result"><div><strong>${mode==='charge'?'↘ Charge':'↗ Discharge'} 20 kW</strong><span class="${e.safe?'good':'danger'}">${e.safe?'WITHIN LIMITS':'LIMIT EXCEEDED'}</span></div><p>Local transformer <b>${fmt(e.localLoading,1)}%</b></p><p>Lowest feeder voltage <b>${fmt(e.minVoltage,3)} pu</b></p><p>Overloaded transformers <b>${e.overloaded}</b></p></div>`}).join('')}</article>`}).join('')}</div><div class="experiment-bottom"><p>The market benchmark stays <strong>$1.58 / Core / day</strong> everywhere in the zone (DERIVED, research report). This ranking adds a grid-side input to install scheduling.</p><button class="primary" id="plan-battery">${state.planned===id?'Keep this planned location':'Plan this as the next build'}<span>↗</span></button></div>`);
 $('#plan-battery').onclick=()=>{state.planned=id;state.selected=id;dialog.close();render();toast(`${h.label} pinned as your next build. You can test another location anytime.`)};
}
function openAbout(){if(!data)return;showDialog(`<span class="eyebrow">MODEL & SOURCES</span><h2 class="dialog-title">A real feeder. A controlled story.</h2><p class="dialog-intro">OpenDSS judges every displayed voltage and transformer violation. The browser replays stored solutions, so the demo keeps working without a live grid feed.</p><div class="source-list"><p><strong>Topology:</strong> <a href="https://data.openei.org/submissions/2981" target="_blank" rel="noreferrer">NREL SMART-DS</a>, AUS P1U, <code>p1uhs19_1247--p1udt17263</code>, CC BY 4.0. 1,010 unique load buses, 379 transformers. These are synthetic connections—not real customer records.</p><p><strong>Geography:</strong> Oncor-suburb stand-in settled at LZ_NORTH. Coordinates originate in north Austin; this does not assert actual Oncor service territory. The map is a stretched topology diagram. District names are fictional narrative labels.</p><p><strong>Physics:</strong> <a href="https://dss-extensions.org/OpenDSSDirect.py/" target="_blank" rel="noreferrer">OpenDSSDirect.py 0.9.4</a>, 5-minute snapshot solves. Limits are 0.95–1.05 pu and 100% transformer winding kVA. The controller estimates headroom, then uses OpenDSS to check and curtail its allocation.</p><p><strong>Deliberate shaping:</strong> ${esc(data.model.shaping.description)} The changed segment is <code>${esc(data.model.shaping.weakLine)}</code>, ${fmt(data.model.shaping.originalLengthKm,3)} → ${fmt(data.model.shaping.modifiedLengthKm,3)} km electrical length.</p><p><strong>Replay inputs — ASSUMPTION:</strong> price traces are scripted, and loads are scaled SMART-DS nameplates. They are not measured July 2026 ERCOT prices, ResStock time series, or weather-rescaled profiles. 96 modeled Core batteries, including a deliberately dense 24-home cohort. No live-data dependency.</p><p><strong>Devices:</strong> ±20 kW Core; 37 kWh usable and 89% round-trip efficiency are ASSUMPTIONS. Hard 20% backup reserve. The browser uses interval averages; 0–120 s start jitter and annual cycle ageing are not modeled. Comms-loss behavior is UNVERIFIED and parameterized but not exercised here.</p><p><strong>Detector — ASSUMPTION:</strong> a fictional ±350 W alternating signal, seeded 45 W meter noise, and 0.00002 pu voltage noise threshold. Four sustained samples plus residual correlation and voltage corroboration are required. False-positive rate describes this seeded replay only; it is not field validation. Quarantine is a simulated exclusion flag.</p><p><strong>Siting:</strong> ${ranked.length} eligible candidates × 3 scenarios × charge/discharge. Dimensionless weights are exposed in the siting panel. The $1.58/day market benchmark is DERIVED in your research report, not a computed revenue forecast. The grid-side score is a hackathon proposal, not an existing Base product.</p><p><strong>Intentional implementation choice:</strong> a local SVG topology view keeps the replay independent of map tiles and works offline once loaded. Python source, raw feeder files, replay CSV, tests, and model limitations are included in the project.</p></div><button class="outline" id="download-replay">Download current replay CSV ↓</button>`);$('#download-replay').onclick=downloadReplay}
function downloadReplay(){const frames=data.replays[state.scenario][state.policy+(state.scenario==='covert'&&state.response==='quarantine'?'_quarantine':'')],header=['time','feeder_mw','max_transformer_pct','min_voltage_pu','target_kw','delivered_kw','shortfall_kw','flagged_units'];const rows=frames.map(f=>[timeLabel(f.minute),f.feederMW,f.maxLoading,f.minVoltage,f.targetKW,f.deliveredKW,f.shortfallKW,f.flags.length]);const blob=new Blob([[header,...rows].map(r=>r.join(',')).join('\n')],{type:'text/csv'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=`hugging-base-${state.scenario}-${state.policy}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){
 $$('[data-scenario]').forEach(b=>b.onclick=()=>setScenario(b.dataset.scenario));$$('[data-layer]').forEach(b=>b.onclick=()=>setLayer(b.dataset.layer));
 $('#play').onclick=()=>state.playing?stop():play();$('#restart').onclick=()=>setStep(0);$('#timeline').oninput=e=>setStep(Number(e.target.value));
 $('#speed').onclick=()=>{state.speed=state.speed===1?2:state.speed===2?4:1;$('#speed').textContent=state.speed+'×';if(state.playing)play()};
 $('#browse-map').onclick=()=>{showDialog('<span class="eyebrow">FEEDER CONNECTIONS</span><h2 class="dialog-title">Inspect a home.</h2><label class="all-candidates-label" for="candidate-select">Choose any modeled connection</label><select id="candidate-select"><option value="">Choose a home…</option>'+data.topology.homes.map(h=>`<option value="${h.id}">${h.label} · ${h.battery?'Existing battery':'Uninstalled'} · ${h.district}</option>`).join('')+'</select>');$('#candidate-select').onchange=e=>{if(e.target.value){const id=e.target.value;dialog.close();selectHome(id);focusHome(id)}}};$('#open-siting').onclick=openSiting;$('#about-button').onclick=openAbout;$('.dialog-close').onclick=()=>{dialog.close();state.experiment=false};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
 $('#zoom-in').onclick=()=>zoom(1.3);$('#zoom-out').onclick=()=>zoom(1/1.3);$('#reset-view').onclick=()=>{view={x:0,y:0,z:1};transformView()};
 const map=$('#map');let drag=null;
 map.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y,moved:false};map.setPointerCapture(e.pointerId)});
 map.addEventListener('pointermove',e=>{if(!drag)return;const rect=map.getBoundingClientRect(),dx=(e.clientX-drag.x)*1000/rect.width,dy=(e.clientY-drag.y)*660/rect.height;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(drag.moved){view.x=drag.vx+dx;view.y=drag.vy+dy;transformView()}});
 map.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-home]');if(target)selectHome(target.dataset.home);else{const pos=new DOMPoint(e.clientX,e.clientY).matrixTransform($('#map-world').getScreenCTM().inverse());const closest=data.topology.homes.map(h=>{const p=point(h.coordinates);return {id:h.id,d:Math.hypot(p[0]-pos.x,p[1]-pos.y)}}).sort((a,b)=>a.d-b.d)[0];if(closest.d<16/view.z)selectHome(closest.id)}}drag=null});map.addEventListener('pointercancel',()=>drag=null);
 map.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.1:1/1.1)},{passive:false});
 map.addEventListener('keydown',e=>{if(['+','=','-','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='+'||e.key==='=')zoom(1.3);else if(e.key==='-')zoom(1/1.3);else{view.x+=e.key==='ArrowLeft'?40:e.key==='ArrowRight'?-40:0;view.y+=e.key==='ArrowUp'?40:e.key==='ArrowDown'?-40:0;transformView()}}});
 document.addEventListener('keydown',e=>{if(e.code==='Space'&&!dialog.open&&!['INPUT','BUTTON','SELECT','TEXTAREA','A'].includes(document.activeElement.tagName)){e.preventDefault();state.playing?stop():play()}});
}
async function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const tools=[{name:'read_grid_simulation',description:'Read the current scenario, dispatch policy, replay time, and solved grid metrics.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({scenario:state.scenario,policy:state.policy,step:state.step,metrics:{minVoltage:current().minVoltage,maxLoading:current().maxLoading,shortfallKW:current().shortfallKW,flagged:current().flags.length},plannedHome:state.planned})},{name:'configure_grid_replay',description:'Select a scenario, dispatch strategy, and time in the visible replay. Does not control real equipment.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(SCENARIOS)},policy:{type:'string',enum:['naive','aware']},step:{type:'integer',minimum:0,maximum:12}},required:['scenario','policy','step'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!SCENARIOS[input.scenario]||!['naive','aware'].includes(input.policy)||!Number.isInteger(input.step)||input.step<0||input.step>12)throw new Error('Invalid replay configuration');setScenario(input.scenario);state.policy=input.policy;setStep(input.step);return{scenario:state.scenario,policy:state.policy,time:timeLabel(current().minute),minVoltage:current().minVoltage,maxLoading:current().maxLoading}}},{name:'inspect_battery_candidate',description:'Open the visible, precomputed six-case placement experiment for an eligible home.',inputSchema:{type:'object',properties:{homeId:{type:'string'}},required:['homeId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!candidatesById.has(input.homeId))throw new Error('Unknown eligible candidate home');selectHome(input.homeId);openExperiment(input.homeId);const c=candidatesById.get(input.homeId);return{homeId:c.id,rank:c.rank,score:c.score,effects:c.effects}}}];
 for(const tool of tools){try{await context.registerTool(tool,{signal:lifecycle.signal})}catch(err){console.warn('Optional WebMCP registration unavailable',err.message)}}
}
async function init(){try{const files=['topology','replays','candidates','model'];const values=await Promise.all(files.map(async name=>{const r=await fetch(name+'.json');if(!r.ok)throw new Error(`Could not load ${name}`);return r.json()}));data=Object.fromEntries(files.map((k,i)=>[k,values[i]]));homesById=new Map(data.topology.homes.map(h=>[h.id,h]));rank();const coords=data.topology.homes.map(h=>h.coordinates),xs=coords.map(c=>c[0]),ys=coords.map(c=>c[1]);projection={xmin:Math.min(...xs),ymax:Math.max(...ys),dx:Math.max(...xs)-Math.min(...xs),dy:Math.max(...ys)-Math.min(...ys)};bind();render();await registerTools()}catch(err){$('#map-loading').textContent='The replay could not load. Refresh to retry.';$('#mission').innerHTML='<h2>Replay unavailable</h2><p class="mission-copy">The data files are missing or could not be read. Refresh the page to try again.</p><button class="primary" id="retry">Retry ↗</button>';$('#retry').onclick=()=>location.reload();console.error(err)}}
init();
